parameters.jsCode:
const posts = $input.all();
const extracted = posts.map(p => ({
  id: p.json.id,
  title: p.json.title?.rendered || p.json.title || '',
  url: p.json.link || '',
  slug: p.json.slug || '',
  categories: p.json.categories || [],
  tags: p.json.tags || []
})).filter(p => p.title.length > 0);

return [{
  json: {
    existingPosts: extracted,
    totalCount: extracted.length,
    titles: extracted.map(p => p.title.toLowerCase()),
    slugs: extracted.map(p => p.slug)
  }
}];

