parameters.jsCode:
const raw = $json.message?.content || $json.text || '';
let data = {};
try {
  const c = raw.replace(/```json/g,'').replace(/```/g,'').trim();
  data = JSON.parse(c);
} catch(e) {
  throw new Error('Parse error in gap analysis: ' + e.message);
}

const gaps = [];
(data.content_gaps || []).forEach(area => {
  (area.missing_topics || []).forEach(t => {
    gaps.push({
      practice_area: area.practice_area,
      title: t.title,
      keyword: t.keyword,
      target_state: t.target_state || 'Federal',
      priority: Number(t.priority) || 5,
      reason: t.reason
    });
  });
});

gaps.sort((a, b) => b.priority - a.priority);

return [{
  json: {
    coverageSummary: data.coverage_summary || {},
    identifiedGaps: gaps,
    gapCount: gaps.length
  }
}];

const ts = new Date().toISOString();
const gaps = $json.identifiedGaps || [];

return [{
  json: {
    generated_at: ts,
    source: 'WF1 Content Gap Analysis',
    coverage_summary: $json.coverageSummary,
    total_gaps_found: $json.gapCount,
    top_opportunities: gaps.slice(0, 10).map((g, i) => ({
      rank: i + 1,
      practice_area: g.practice_area,
      title: g.title,
      primary_keyword: g.keyword,
      target_state: g.target_state,
      priority_score: g.priority,
      gap_reason: g.reason
    })),
    all_gaps: gaps
  }
}];
